"""Create exact component origin records without changing production notices."""
from pathlib import Path
import json,zipfile,hashlib
ROOT=Path(__file__).resolve().parents[2];OWNER=ROOT.parents[1]
PASS=ROOT/'docs/history/implementation-passes/energy-chamber-hybrid-proof-v1'
ART='Assets/_Game/ArtProof/EnergyChamber';VR3='Assets/_Game/Content/VisualReplacementV3'
intake=json.loads((PASS/'intake-candidates.json').read_text());rows=[]
for name,usage in [('Foundation','octagonal cast foundation, open supported service annulus and raised pressure seat'),('CentralChamber','segmented vessel shell, frame tie rods, bearing rings, crown and confined energy inspection slots'),('Connector','continuous paired feed/return routes, union flanges, tailored carrier bridges and cable channels'),('SideNode','shared node footing, docking manifold and mechanical mounting surfaces')]:
    rows.append(dict(component=name,origin='CUSTOM GEOMETRY',source='art/energy-chamber-hybrid-proof-v1/EnergyChamber_HybridProof.blend',authoringScript='Tools/energy-chamber-hybrid-proof-v1/author.py',unityModel=f'{ART}/Models/EC_{name}.fbx',usage=usage,license='project-owned'))
for name,derived,usage in [('Generator','generator','one existing generator per node, uniformly normalized and rotated'),('Centrifuge','centrifuge','one existing secondary control/distribution mechanism per node'),('Prop_PipeHolder','proppipeholder','existing support mechanism on each carrier bridge')]:
    source=next(r for r in intake if Path(r['entry']).stem==name and not r['licenseEvidence'])
    rows.append(dict(component=name,origin='DONOR-DERIVED',sourcePackage=source['package'],originalArchive=source['archive'],originalEntry=source['entry'],sourceSha256=source['sha256'],unityPrefab=f'{VR3}/Prefabs/VR3_{derived}.prefab',unityModel=f'{VR3}/Models/VR3_{derived}.fbx',material=f'{ART}/Materials/EC_DonorMachinery.mat',usage=usage,newImport=False,license='CC0-1.0'))
archive=next((OWNER/'ExternalAssetIntake/Current/quaternius-modular-scifi-megakit-standard').glob('*.zip'))
with zipfile.ZipFile(archive) as z:
    entry=next(n for n in z.namelist() if n.endswith('/Platform_Metal.fbx') and '/FBX/' in n)
    rows.append(dict(component='inspection ground',origin='DONOR-DERIVED',sourcePackage='quaternius-modular-scifi-megakit-standard',originalArchive=str(archive),originalEntry=entry,sourceSha256=hashlib.sha256(z.read(entry)).hexdigest(),unityPrefab=f'{VR3}/Prefabs/VR3_platformmetal.prefab',unityModel=f'{VR3}/Models/VR3_platformmetal.fbx',usage='review backdrop only; 49 existing panels, excluded from installation metrics',newImport=False,license='CC0-1.0'))
for item in json.loads((PASS/'promoted-donors.json').read_text()):
    rows.append(dict(component=Path(item['entry']).stem,origin='EXTERNAL DONOR',sourcePackage=item['package'],originalArchive=item['archive'],originalEntry=item['entry'],archiveSha256=item['archiveSha256'],sourceSha256=item['sha256'],unityModel=item['unityPath'].replace('\\','/'),usage=item['usage']+'; native UV and FBX axis/unit conversion preserved, uniform placement scale',materialSource='Assets/_Game/Content/BlueprintWorldR1/Materials/R1_Trim1.mat and R1_Trim2.mat',newImport=True,license='CC0-1.0'))
rows.append(dict(component='G-0 scale reference',origin='EXISTING ASSET',unityPrefab='Assets/_Game/Content/VisualSlice/Prefabs/G0_V3_Live_Tier0.prefab',authoritativeBinding='Assets/_Game/Content/Definitions/S07_Evolution.asset _tierOverrides[0]',usage='unchanged current bipedal Tier 0, localScale 1,1,1; presentation scripts disabled only on proof scene instance',newImport=False,license='project-owned with previously recorded CC BY Catfish internal-mechanism credit'))
rows.append(dict(component='authored material library',origin='EXISTING ASSET',source='Assets/_Game/Content/CapacitorFieldProof/Textures/',maps=[f'Assets/_Game/Content/CapacitorFieldProof/Textures/CF_{name}_{suffix}.png' for name in ['Graphite','Shell','Steel','Deck','Ceramic','Warning','Coil','Cold'] for suffix in ['BaseColor','Normal','MetallicSmoothness','Occlusion']],usage='existing project-owned manufactured-metal PBR maps; separate proof-only EC materials, metre-space UVs',newImport=False,license='project-owned'))
rows.append(dict(component='donor material and trim surfaces',origin='EXISTING ASSET',materials=[f'{VR3}/Materials/VR3_WornIndustrialAtlas.mat','Assets/_Game/Content/BlueprintWorldR1/Materials/R1_Trim1.mat','Assets/_Game/Content/BlueprintWorldR1/Materials/R1_Trim2.mat'],usage='native donor UVs and existing normal/metallic/occlusion maps; machinery material cloned under proof with restrained emission',newImport=False,license='CC0 derivatives / project-owned authored processing'))
(PASS/'asset-origin.json').write_text(json.dumps(rows,indent=2),encoding='utf-8')
print('EXACT_COMPONENT_ORIGINS',len(rows),'NEW_MODELS',sum(r.get('newImport',False) for r in rows))
